// CPACK → LOCAL AGENT tee — Direction B (ADR-0042 §2.3).
// Place on a SECOND wire off your PLC read / assembly node (a tee, not a redirect).
// Sends RAW tags to the local sparkplug-agent's POST /v1/tags; the AGENT builds
// SparkPlug B and does the mTLS uplink. Key is env CPACK_INGEST_KEY (the local
// tee↔agent shared secret) — NEVER hardcoded.

const key = env.get("CPACK_INGEST_KEY");
if (!key) {
    node.error("CPACK_INGEST_KEY env var is not set — refusing to POST without an ingest key", msg);
    return null;
}

// Normalize the upstream output into the agent's /v1/tags rawtag envelope:
//   { group, scan_ts, tags: [ { metric, value, long? } ] }
// `metric` MUST match a raw_tag_map metric_suffix in cpack-agent.yaml (e.g.
// "/CELULA1/CER400/Admin/ProdConsumedCount"). Unmatched tags increment the agent
// metric sparkplug_agent_raw_dropped_total{reason="unmapped"} (reject-don't-drop),
// so a wrong name is VISIBLE, not silent. Adapt the .metric/.value pull below to
// your assembly node's field names.
let src = msg.payload;
if (src && Array.isArray(src.metrics)) src = src.metrics;   // {metrics:[…]} → […]
if (!Array.isArray(src) || src.length === 0) {
    node.warn("tee: payload has no tags/metrics[]; skipping");
    return null;
}
const tags = src.map(m => {
    const t = { metric: m.metric || m.name, value: m.value };
    if (m.long === true) t.long = true;   // optional int hint; agent config is authoritative
    return t;
}).filter(t => t.metric != null && t.value != null);
if (tags.length === 0) {
    node.warn("tee: no {metric,value} pairs after mapping; skipping");
    return null;
}

msg.headers = { "Content-Type": "application/json", "X-Ingest-Key": key };
msg.payload = { group: "CPACK", scan_ts: Date.now(), tags };
return msg;
